eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   stories: () => (/* binding */ stories)\n/* harmony export */ });\nconst stories = [\n    {\n        id: 'story-01',\n        slug: 'the-seed-keeper-of-debre-zeit',\n        personName: 'Ato Bekele Tadesse',\n        role: {\n            en: 'Master Teff Farmer & Seed Conservator',\n            am: 'የጤፍ አርሶ አደርና የዘር ጠባቂ'\n        },\n        location: 'Ada\\'a Woreda, Debre Zeit',\n        generation: '4th Generation Highland Farmer',\n        quote: {\n            en: 'When I hold a handful of Magna teff seeds in the morning mist, I am holding four generations of my ancestors\\' sweat, prayer, and patience.',\n            am: 'በማለዳው ጤፉን በእጄ ሳፈራው የአያቶቼን ድካም፣ ጸሎትና ትዕግሥት አያለሁ።'\n        },\n        body: {\n            en: [\n                'Ato Bekele manages a family parcel where the soil has been tilled by ox-drawn plows (Maresha) for over a century. He specializes in pure Magna white teff.',\n                '\"The secret of good teff,\" he explains, \"is never rushing the ground. We let the soil drink the summer rains (Kiremt), we winnow the seed against the wind, and we select only the plumpest heads for the next season\\'s sowing.\"',\n                'His grain is sought out across the central highlands for its sweet natural finish and remarkable fermentation vigor.'\n            ],\n            am: [\n                'አቶ በቀለ ከአያቶቻቸው የወረሱትን ለም መሬት በጥንቃቄ በማረስ ጥራት ያለው ነጭ ጤፍ ያመርታሉ።',\n                '\"የጥሩ ጤፍ ሚስጥሩ መሬቱን አለማስጨነቅ ነው፤ የክረምቱን ዝናብ ጠጥቶ በንፋስ ሲበጠር ምርጡን ዘር ለቀጣዩ አመት እናስቀራለን\" ይላሉ።',\n                'የእርሳቸው ጤፍ በጣዕሙና በጥራቱ በብዙዎች ዘንድ ተመራጭ ነው።'\n            ]\n        },\n        culturalContext: {\n            en: 'Ada\\'a woreda in the Shewa highlands features volcanic loam with exceptional mineral content, producing teff prized for celebratory holiday feasts.',\n            am: 'የአዳእ ወረዳ ለም አፈር ከፍተኛ ማዕድናትን የያዘ በመሆኑ ለበዓላት የሚመረጡ ምርጥ ጤፎች የሚገኙበት ነው።'\n        },\n        isDemoData: true\n    },\n    {\n        id: 'story-02',\n        slug: 'the-living-sourdough-of-lalibela',\n        personName: 'Emaye Almaz Haile',\n        role: {\n            en: 'Traditional Kitchen Baker & Ersho Steward',\n            am: 'የጓዳ ባለሙያና የእርሾ ጠባቂ'\n        },\n        location: 'Lalibela Highlands, Amhara',\n        generation: 'Elder Cook (Ye\\'Injera Enat)',\n        quote: {\n            en: 'My ersho jar was given to me by my mother on my wedding day forty years ago. That living starter has traveled through time, blessing every single morning loaf.',\n            am: 'የእርሾ እቃዬን እናቴ ከ40 ዓመታት በፊት በሰርጌ ቀን የሰጠችኝ ነው። ያ ሕያው እርሾ ዛሬም ድረስ ቤቴን ይባርካል።'\n        },\n        body: {\n            en: [\n                'In her hillside kitchen overlooking the rock-hewn churches of Lalibela, Emaye Almaz bakes over eighty injeras every fasting and feast day.',\n                '\"Making injera is a conversation between your hands, the clay, and the weather,\" she smiles. \"When the highland wind is cold, you wrap the borena pot like a newborn child. When you pour, your mind must be as calm as still water.\"',\n                'Neighbors still bring small jars of flour to her kitchen to receive a spoonful of her active starter culture.'\n            ],\n            am: [\n                'በላሊበላ ተራሮች ግርጌ ባለው ጓዳቸው ውስጥ እማዬ አልማዝ በየበዓላቱ ከ80 በላይ እንጀራዎችን ይጋግራሉ።',\n                '\"እንጀራ መጋገር ከእጅህ፣ ከሸክላውና ከአየሩ ጋር መነጋገር ነው። አየሩ ሲቀዘቅዝ እቃውን እንደ ህጻን ትሸፍነዋለህ፤ ስታፈስስ ደግሞ ልብህ ረጋ ማለት አለበት\" ይላሉ።',\n                'ጎረቤቶቻቸው ዛሬም ድረስ እርሾ ለመቀበል ወደ እሳቸው ይመጣሉ።'\n            ]\n        },\n        culturalContext: {\n            en: 'Starters (ersho) are traditionally preserved by leaving a cup of fermented batter in the base of the clay bowl to inoculate the next batch.',\n            am: 'እርሾ ከቀደመው ሊጥ ላይ በማስቀረት የሚቀጥለውን ሊጥ ለማብላላት የሚተላለፍ የዘመናት ጥበብ ነው።'\n        },\n        isDemoData: true\n    },\n    {\n        id: 'story-03',\n        slug: 'the-diaspora-mesob-in-dc',\n        personName: 'Chef Senait Gebru',\n        role: {\n            en: 'Diaspora Restaurateur & Cultural Ambassador',\n            am: 'የባህል ምግብ አብሳይና አምባሳደር'\n        },\n        location: 'Washington D.C., USA',\n        generation: '1st Generation Diaspora',\n        quote: {\n            en: 'In our restaurant, when a group of college students or diplomats sits around one Mesob and shares a gursha for the first time, borders dissolve.',\n            am: 'በሬስቶራንታችን ሰዎች በአንድ መሶብ ዙሪያ ተቀምጠው ሲጎራረሱ የባህልና የድንበር ልዩነት ይጠፋል።'\n        },\n        body: {\n            en: [\n                'Senait moved to the United States in the late 1990s. Sourcing 100% Ethiopian-grown teff was once impossible, but today she works with direct-import cooperatives.',\n                '\"People often ask why we don\\'t give everyone individual small plates,\" she shares. \"I tell them: the injera is not just bread. The injera is the table. To tear from the same leaf is to say we are family.\"'\n            ],\n            am: [\n                'ሰናይት ወደ ውጭ አገር ከሄደች በኋላ የኢትዮጵያን ምግብ ባህል በውጭው ዓለም በማስተዋወቅ ላይ ትገኛለች።',\n                '\"ሰዎች ለምን ለየብቻ ሳህን አታቀርቡም ብለው ይጠይቁኛል። እኔ ግን እንጀራ መመገቢያ ብቻ ሳይሆን የአንድነት መድረክ መሆኑን አስረዳቸዋለሁ\" ትላለች።'\n            ]\n        },\n        culturalContext: {\n            en: 'Washington D.C. hosts the largest Ethiopian diaspora community outside of Addis Ababa, with Little Ethiopia on U Street serving as a hub of food culture.',\n            am: 'ዋሽንግተን ዲሲ ከሀገር ውጭ ትልቁ የኢትዮጵያውያን ማህበረሰብ የሚገኝበትና የሀበሻ ምግብ የሚዘወተርበት ከተማ ነው።'\n        },\n        isDemoData: true\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./data/stories.ts\n");

